"""One-shot exact publication check. No commit/push or numerical execution."""
from pathlib import Path
import hashlib,json,subprocess
R=Path(__file__).resolve().parents[4];D=Path(__file__).resolve().parent
NAMES = ['diagnostics/direct-lu-markowitz/reproduce/correctness.jl', 'diagnostics/direct-lu-markowitz/reproduce/direct-factor.jl', 'diagnostics/direct-lu-markowitz/reproduce/factor-export.jl', 'diagnostics/direct-lu-markowitz/reproduce/fixtures.jl', 'diagnostics/direct-lu-markowitz/reproduce/prepare-overlay.py', 'diagnostics/direct-lu-markowitz/reproduce/red.jl', 'diagnostics/simplex-core-architecture/DIRECT-LU-PREPARATION.md', 'diagnostics/simplex-core-architecture/STATUS.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/STATUS.md.before-preparation', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/baseline.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/closure.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/closure.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/continuation.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/host.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/initial/correctness.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/initial/direct-factor.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/initial/factor-export.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/initial/fixtures.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/initial/prepare-overlay.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/initial/red.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/initial/report.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/overlay-initial.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/publication.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/publication.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-final-bindings.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-final.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-fix.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-fix.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-initial-bindings.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-initial.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-oracle-supplement.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/review-oracle-supplement.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/roadmap.md.before-preparation', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-PREPARATION/source-check-initial.json', 'docs/superpowers/plans/2026-10-11-simplex-core-architecture.md']
def git(*args):return subprocess.check_output(['git',*args],cwd=R,text=True).strip()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
closure=json.loads((D/'closure.json').read_text())
if not closure['all_passed'] or not all(sha(R/n)==h for n,h in closure['sha256'].items()):raise SystemExit('Closure failed or bindings changed')
if git('diff','--cached','--name-only'):raise SystemExit('Index must start empty')
selfname=str((D/'publication.json').relative_to(R));other=[n for n in NAMES if n!=selfname]
if any(not (R/n).is_file() for n in other):raise SystemExit('Missing declared file')
subprocess.run(['git','add','--',*other],cwd=R,check=True)
if sorted(git('diff','--cached','--name-only').splitlines())!=sorted(other):raise SystemExit('Initial exact staged set mismatch')
blobs={n:git('rev-parse',':'+n) for n in other}
if any(git('hash-object',n)!=h for n,h in blobs.items()):raise SystemExit('Staged/working mismatch')
subprocess.run(['git','diff','--cached','--check'],cwd=R,check=True)
with (D/'publication.json').open('x') as f:json.dump({'all_passed':True,'scope':'OFFLINE candidate/test preparation; no Julia execution or production promotion','exact_names':NAMES,'staged_blobs_excluding_self':blobs,'sha256':{n:sha(R/n) for n in other},'self_binding':'Included in exact staged set, bound by committed tree; postcommit verifies actual self blob too.'},f,indent=2);f.write('\n')
subprocess.run(['git','add','--',selfname],cwd=R,check=True)
if sorted(git('diff','--cached','--name-only').splitlines())!=NAMES:raise SystemExit('Final exact staged set mismatch')
subprocess.run(['git','diff','--cached','--check'],cwd=R,check=True)
print(json.dumps({'all_passed':True,'exact_staged_names':len(NAMES),'bound_other_blobs':len(blobs)}))
